/**
 * aiwmc.evidence.v1 contract tests (Phase 1, contract set item 2): the schema's own
 * rules, and one adapter suite per legacy schema. Fixtures:
 *  - analytica-evidence-v1.packet.json: produced by Analytica's own PredictaEvidencePort
 *    on its test fixture (analytica-cf apps/api/tests/test_evidence_port.py).
 *  - system-a.*.json: System A's committed fixtures (feature/evidence-service,
 *    docs/evidence-service/fixtures), generated by its real pipeline with mocked Tavily.
 *  - predicta-search-v1.response.json: authored to Predicta's schema (it has no valid fixture).
 */
import { describe, expect, it } from 'vitest';
import { createHash } from 'node:crypto';
import { readFileSync } from 'node:fs';
import { resolve } from 'node:path';
import {
  adaptAnalyticaEvidenceV1,
  adaptPredictaSearchV1,
  adaptSystemAPacket,
  EvidencePacketV1Schema,
  evidenceContentHash,
  finalizeEvidencePacket,
  sha256Utf8,
  systemALegacyPacketHash,
  type EvidencePacketV1,
} from '../../supabase/functions/_shared/contracts/index.ts';
import { canonicalJson } from '../../supabase/functions/_shared/canonical-json.ts';

const fixture = (name: string) =>
  JSON.parse(readFileSync(resolve(__dirname, 'fixtures/evidence', name), 'utf8'));
const clone = <T>(v: T): T => JSON.parse(JSON.stringify(v));

const analytica = fixture('analytica-evidence-v1.packet.json');
const predicta = fixture('predicta-search-v1.response.json');
const coffee = fixture('system-a.coffee-shop-denver.json').packet;
const saas = fixture('system-a.saas-startup-austin.json').packet;

describe('sha256 (pure TS)', () => {
  it.each(['', 'abc', 'Coffee shops — €1,2 ✓', 'x'.repeat(1000)])('matches node:crypto for %#', (s) => {
    expect(sha256Utf8(s)).toBe(createHash('sha256').update(s, 'utf8').digest('hex'));
  });
  it('NIST vector', () => {
    expect(sha256Utf8('abc')).toBe('ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad');
  });
});

describe('legacy hashes the adapters rely on', () => {
  it('System A packet hashes recompute exactly (both fixtures)', () => {
    expect(systemALegacyPacketHash(coffee)).toBe('8ee196e1bd40fc27b7b91adda829ad2ea5d012bd77b12254c8646776e4cd6a38');
    expect(coffee.contentHash).toBe('8ee196e1bd40fc27b7b91adda829ad2ea5d012bd77b12254c8646776e4cd6a38');
    expect(systemALegacyPacketHash(saas)).toBe(saas.contentHash);
  });
  it('Analytica snapshot hash recomputes (no floats in it)', () => {
    const s = analytica.sources[0];
    const hash = sha256Utf8(canonicalJson({
      canonical_url: s.canonical_url, title: s.title, publisher: s.publisher, publication_date: s.publication_date, text: s.snapshot.text,
    }));
    expect(hash).toBe('53b9684557a9a24d63740de6f6d4a1fae03fb29eff5b5f4971623051330c9cc7');
  });
  it('Analytica packet hash does NOT recompute in JS (Python writes 1.0), so it stays opaque', () => {
    const { schema_version: _s, upstream_api_version: _u, packet_id: _p, lineage: _l, ...rest } = analytica;
    const content = { ...rest, subject: { submitted_name: rest.subject.submitted_name, geography: rest.subject.geography, industry: rest.subject.industry } };
    expect(sha256Utf8(canonicalJson(content))).not.toBe(analytica.lineage.content_hash);
  });
});

describe('aiwmc.evidence.v1 schema rules', () => {
  const good = adaptSystemAPacket(coffee);
  const reparse = (mutate: (p: EvidencePacketV1) => void, rehash = true) => {
    const p = clone(good);
    mutate(p);
    if (rehash) p.integrity.content_hash = evidenceContentHash(p);
    return EvidencePacketV1Schema.safeParse(p);
  };
  const messages = (r: ReturnType<typeof reparse>) => (r.success ? [] : r.error.issues.map((i) => i.message).join(' | '));

  it('accepts an adapted packet and is stable across re-finalising', () => {
    expect(EvidencePacketV1Schema.safeParse(good).success).toBe(true);
    const { packet_id: _p, integrity: _i, ...draft } = good;
    expect(finalizeEvidencePacket(draft)).toEqual(good);
    expect(good.packet_id).toBe(`aep_${good.integrity.content_hash.slice(0, 24)}`);
  });

  it('content hash ignores packet_id and created_at, and changes with content', () => {
    expect(evidenceContentHash({ ...good, packet_id: 'x', created_at: null })).toBe(good.integrity.content_hash);
    const changed = clone(good);
    changed.claims[0].statement += '.';
    expect(evidenceContentHash(changed)).not.toBe(good.integrity.content_hash);
  });

  it('rejects a tampered packet', () => {
    expect(messages(reparse((p) => { p.claims[0].statement = 'edited'; }, false))).toMatch(/content_hash does not match/);
  });

  it('rejects a passage whose sha256 is not its text hash', () => {
    expect(messages(reparse((p) => { p.passages[0].text = 'different text'; }))).toMatch(/sha256 does not match text/);
  });

  it('rejects a link to a passage of a different source (unchecked before v1)', () => {
    expect(messages(reparse((p) => { p.claims[0].evidence[0].passage_id = p.passages[4].passage_id; }))).toMatch(/belongs to/);
  });

  it('rejects dangling references and duplicate ids', () => {
    expect(messages(reparse((p) => { p.passages[0].source_id = 'nope'; }))).toMatch(/unknown source nope/);
    expect(messages(reparse((p) => { p.sources.push(clone(p.sources[0])); }))).toMatch(/duplicate source id/);
    expect(messages(reparse((p) => {
      p.contradictions.push({ contradiction_id: 'c1', claim_id: 'missing', supporting_passage_ids: [], contradicting_passage_ids: ['zzz'], explanation: null, status: 'open' });
    }))).toMatch(/unknown claim missing.*unknown passage zzz/);
  });

  it('snapshot: captured needs a hash and a full_allowed policy; not_captured carries none', () => {
    const captured = { status: 'captured' as const, sha256: 'a'.repeat(64), byte_length: 10, media_type: 'text/html', storage_ref: null };
    expect(messages(reparse((p) => { p.sources[0].snapshot = captured; }))).toMatch(/full_allowed/);
    expect(reparse((p) => { p.sources[0].snapshot = captured; p.sources[0].policy.storage = 'full_allowed'; }).success).toBe(true);
    expect(messages(reparse((p) => { p.sources[0].snapshot = { ...captured, sha256: null }; p.sources[0].policy.storage = 'full_allowed'; }))).toMatch(/needs sha256/);
    expect(messages(reparse((p) => { p.sources[0].snapshot.sha256 = 'b'.repeat(64); }))).toMatch(/cannot carry sha256/);
  });

  it('rejects non-http URLs, bad timestamps, training permission and unknown fields', () => {
    expect(reparse((p) => { p.sources[0].url = 'javascript:alert(1)'; }).success).toBe(false);
    expect(reparse((p) => { p.sources[0].retrieved_at = 'not-retrieved'; }).success).toBe(false);
    expect(reparse((p) => { (p.sources[0].policy as { can_train: boolean }).can_train = true; }).success).toBe(false);
    expect(reparse((p) => { (p.sources[0] as Record<string, unknown>).extra = 1; }).success).toBe(false);
    expect(reparse((p) => { (p.claims[0] as { status: string }).status = 'SUPPORTED'; }).success).toBe(false);
  });
});

describe('adapter: analytica.evidence.v1', () => {
  const out = adaptAnalyticaEvidenceV1(analytica);

  it('produces a valid v1 packet that keeps every source, passage, claim and contradiction', () => {
    expect(EvidencePacketV1Schema.safeParse(out).success).toBe(true);
    expect(out.sources).toHaveLength(analytica.sources.length);
    expect(out.passages).toHaveLength(analytica.passages.length);
    expect(out.claims).toHaveLength(analytica.claims.length);
    expect(out.contradictions).toHaveLength(analytica.contradictions.length);
  });

  it('maps fields, vocabulary and lineage', () => {
    const s = out.sources[0];
    expect(s).toMatchObject({
      source_id: 'src_001', provider_id: 'census', url: 'https://example.gov/series/packaging',
      title: 'Packaging input-cost series', publisher: 'Example Government Dataset', published_at: '2023-01-15',
      retrieved_at: '2026-09-04T18:00:00Z', source_kind: 'other', primacy: 'primary',
    });
    expect(s.snapshot.status).toBe('not_captured');
    expect(s.legacy?.content_hash).toBe('53b9684557a9a24d63740de6f6d4a1fae03fb29eff5b5f4971623051330c9cc7');
    expect(out.passages[0].legacy_hash).toBe(analytica.passages[0].content_hash);
    expect(out.passages[0].sha256).toBe(sha256Utf8(analytica.passages[0].text));
    expect(out.claims[0]).toMatchObject({ status: 'contested', independent_source_count: 2, limitations: ['Regional and national measures differ.'] });
    expect(out.claims[0].evidence.map((l) => l.relation)).toEqual(['supports', 'contradicts']);
    expect(out.contradictions[0]).toMatchObject({
      claim_id: 'claim_001', supporting_passage_ids: ['passage_src_001'], contradicting_passage_ids: ['passage_src_002'], status: 'open',
    });
    expect(out.subject).toEqual({ name: 'Northstar Packaging', geography: 'New York', industry: 'Packaging manufacturing' });
    expect(out.lineage).toMatchObject({ run_id: 'qry_001', case_id: 'case_001', retrieved_to: '2026-09-04T18:00:01Z', degraded: null });
    expect(out.lineage.upstream.at(-1)).toEqual({ schema: 'analytica.evidence.v1', id: 'ep_9d9890ff9fc80cb8', content_hash: analytica.lineage.content_hash });
    expect(out.lineage.dropped.map((d) => d.field)).toContain('quality');
  });

  it('turns Analytica sentinels into null', () => {
    const raw = clone(analytica);
    raw.sources[0].publisher = 'Unknown publisher';
    raw.sources[0].title = '';
    raw.sources[0].source_type = 'UNKNOWN';
    raw.lineage.retrieved_at = 'not-retrieved';
    const r = adaptAnalyticaEvidenceV1(raw);
    expect(r.sources[0]).toMatchObject({ publisher: null, title: null, source_kind: 'other', primacy: 'unknown' });
    expect(r.lineage.retrieved_to).toBe('2026-09-04T18:00:01Z');
  });

  it('is deterministic', () => {
    expect(adaptAnalyticaEvidenceV1(clone(analytica))).toEqual(out);
  });

  it('rejects what v1 cannot honestly represent', () => {
    const badTime = clone(analytica);
    badTime.sources[0].snapshot.retrieved_at = 'not-retrieved';
    expect(() => adaptAnalyticaEvidenceV1(badTime)).toThrow();
    const badStatus = clone(analytica);
    badStatus.claims[0].status = 'VERIFIED';
    expect(() => adaptAnalyticaEvidenceV1(badStatus)).toThrow(/Unknown Analytica claim status/);
    const crossed = clone(analytica);
    crossed.claims[0].evidence[0].passage_id = 'passage_src_002';
    expect(() => adaptAnalyticaEvidenceV1(crossed)).toThrow(/belongs to/);
    expect(() => adaptAnalyticaEvidenceV1({ ...clone(analytica), schema_version: 'analytica.evidence.v2' })).toThrow();
  });
});

describe('adapter: predicta.search.v1', () => {
  const out = adaptPredictaSearchV1(predicta, {
    predictaVersion: '2026.08.03-1',
    caseId: 'case_001',
    providerPolicies: {
      wikidata: { canRedisplay: true, canCache: true, canPersist: true, license: 'CC0 1.0' },
      wikipedia: { canRedisplay: true, canCache: true, canPersist: true, license: 'CC BY-SA 4.0' },
    },
  });

  it('accepts a real-shaped response with no apiVersion', () => {
    expect(predicta.apiVersion).toBeUndefined();
    expect(EvidencePacketV1Schema.safeParse(out).success).toBe(true);
  });

  it('makes one passage per snippet with the passage_<id> convention claims use', () => {
    expect(out.passages.map((p) => p.passage_id)).toEqual(['passage_wikidata:Q123', 'passage_wikipedia:en:Packaging']);
    expect(out.passages[0]).toMatchObject({ source_id: 'wikidata:Q123', extracted_at: '2026-09-04T18:00:00.000Z' });
  });

  it('maps sources, policy, claims and contradictions', () => {
    expect(out.sources[1]).toMatchObject({ source_kind: 'aggregator', primacy: 'secondary', language: 'en', published_at: null, author: null });
    expect(out.sources[0].policy).toMatchObject({ license: 'CC0 1.0', storage: 'passage_allowed', can_redisplay: true, can_train: false });
    expect(out.claims[0].status).toBe('contested');
    expect(out.contradictions).toHaveLength(1);
    expect(out.lineage).toMatchObject({ run_id: 'q_mh8k2c_1', degraded: false, case_id: 'case_001' });
    expect(out.lineage.produced_by).toEqual({ system: 'predicta', component: 'search', version: '2026.08.03-1' });
  });

  it('without provider policies the sources stay unreviewed', () => {
    const r = adaptPredictaSearchV1(predicta);
    expect(r.sources[0].policy).toMatchObject({ license: null, storage: 'unknown', can_redisplay: null });
  });

  it("records Predicta's own degraded and unverified states as limitations", () => {
    const raw = clone(predicta);
    raw.origin = 'UNVERIFIED';
    raw.candidates = [];
    raw.claims = [];
    raw.diagnostics.providersRequested = [];
    raw.diagnostics.providersSucceeded = [];
    const r = adaptPredictaSearchV1(raw);
    expect(r.sources).toEqual([]);
    expect(r.limitations).toEqual(['Predicta marked this result UNVERIFIED', 'No provider served the requested lens']);
  });

  it('rejects a wrong apiVersion, a missing passage and an unknown status', () => {
    expect(() => adaptPredictaSearchV1({ ...clone(predicta), apiVersion: 'predicta.search.v2' })).toThrow();
    const noSnippet = clone(predicta);
    noSnippet.candidates[1].snippet = '';
    expect(() => adaptPredictaSearchV1(noSnippet)).toThrow(/unknown passage/);
    const badStatus = clone(predicta);
    badStatus.claims[0].status = 'LIKELY';
    expect(() => adaptPredictaSearchV1(badStatus)).toThrow(/Unknown Predicta claim status/);
  });
});

describe('adapter: Quantis System A packet', () => {
  const tavily = { canRedisplay: true, canCache: false, canTrainOnResults: false, termsReviewedAt: '2026-08-10T00:00:00Z', termsReviewCitation: 'tavily.com/terms §3.2(ii), §3.4' };

  it.each([['coffee', coffee], ['saas', saas]])('%s fixture adapts to a valid v1 packet', (_n, packet) => {
    const out = adaptSystemAPacket(packet, { tavily });
    expect(EvidencePacketV1Schema.safeParse(out).success).toBe(true);
    expect(out.sources).toHaveLength(packet.sources.length);
    expect(out.claims).toHaveLength(packet.claims.length);
    expect(out.lineage.upstream[0]).toEqual({ schema: 'quantis.evidence_packet.0.1.0', id: packet.evidencePacketId, content_hash: packet.contentHash });
    expect(out.lineage.gaps).toEqual(packet.unresolvedQuestions);
  });

  it('gives the same v1 content hash Deno computed for the coffee fixture (2026-11-05)', () => {
    expect(adaptSystemAPacket(coffee).integrity.content_hash).toBe('968c0ec0107a0d70028f454e4fbff38418ec9d418cf594c3d0a8c00cdbb944b2');
  });

  it("reproduces System A's passage hashes with v1's own sha256", () => {
    const out = adaptSystemAPacket(coffee);
    for (const p of out.passages) expect(p.sha256).toBe(p.legacy_hash);
  });

  it('moves the title out of publisher and maps enums to lower case', () => {
    const s = adaptSystemAPacket(coffee, { tavily }).sources[0];
    expect(s).toMatchObject({
      title: 'Denver Retail Rent Report 2026', publisher: null, source_kind: 'other', primacy: 'unknown', freshness: 'aging',
      published_at: '2026-02-01',
    });
    expect(s.policy).toMatchObject({ storage: 'metadata_only', can_redisplay: true, can_cache: false, terms_reviewed_at: '2026-08-10T00:00:00Z' });
  });

  it('maps claim status and derives contradictions from CONTRADICTS links', () => {
    const out = adaptSystemAPacket(coffee);
    expect(out.claims.map((c) => c.status)).toEqual(['supported', 'single_source', 'single_source', 'single_source']);
    expect(out.contradictions).toEqual([]);
    const raw = clone(coffee);
    raw.claims[0].support[1].relation = 'CONTRADICTS';
    raw.claims[0].status = 'CONTESTED';
    const r = adaptSystemAPacket(raw);
    expect(r.contradictions[0]).toMatchObject({ claim_id: raw.claims[0].claimId, contradicting_passage_ids: [raw.claims[0].support[1].passageId] });
  });

  it('records dropped numeric observations instead of losing them silently', () => {
    const raw = clone(coffee);
    raw.numericObservations = [{ observationId: 'o1' }];
    expect(adaptSystemAPacket(raw).lineage.dropped).toContainEqual({ field: 'numericObservations', count: 1, reason: 'no v1 type; Phase 2 Observation' });
  });

  it('rejects PARTIALLY_SUPPORTED (System A never had it) and other schema versions', () => {
    const raw = clone(coffee);
    raw.claims[0].status = 'PARTIALLY_SUPPORTED';
    expect(() => adaptSystemAPacket(raw)).toThrow(/Unknown System A claim status/);
    expect(() => adaptSystemAPacket({ ...clone(coffee), evidenceSchemaVersion: '0.2.0' })).toThrow();
  });
});

describe('the three adapters agree on shared evidence', () => {
  it('the same snippet text gets the same passage hash whatever system it came through', () => {
    const fromAnalytica = adaptAnalyticaEvidenceV1(analytica).passages[0];
    const fromPredicta = adaptPredictaSearchV1(predicta).passages[0];
    expect(fromAnalytica.text).toBe(fromPredicta.text);
    expect(fromAnalytica.sha256).toBe(fromPredicta.sha256);
  });
});
